	@Test
	void acceptedOrderOwnerRemainsRetainedUntilItsBlockingChildCloseCompletes() throws Exception {
		CountDownLatch closeEntered = new CountDownLatch(1);
		CountDownLatch releaseClose = new CountDownLatch(1);
		TestTupleFunction producer = rowsFunction();
		KeyFunction key = new KeyFunction();
		RegisteredFunctions registrations = register(producer, key);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		CloseableIteration<BindingSet> result = null;
		try {
			var source = SealedBoundaryTestSupport.source(NativeCompositeOriginFixture.miniData());
			List<BindingSet> ordinary = ordinaryRows(source, producer, key, false);
			assertEquals(3, ordinary.size(), "ordinary full-sort control drains the same generic producer rows");
			assertEquals(List.of("A", "B", "C"), representatives(ordinary));
			producer.closeControl = new ReaderCloseControl(closeEntered, releaseClose, null);
			QueryRoot root = orderedRoot(producer, key, false);
			markOrderSummary(root, false);
			QueryEvaluationStep step = SealedBoundaryTestSupport.nativeStrategy(source, true).precompile(root);
			result = step.evaluate(EmptyBindingSet.getInstance());
			NativeExecutionContext owner = NativeExecutionContextCarrier.contextOf(result);
			assertNotNull(owner);
			CloseableIteration<BindingSet> actualResult = result;
			Future<Boolean> pendingHasNext = executor.submit(actualResult::hasNext);
			assertTrue(closeEntered.await(WAIT_SECONDS, TimeUnit.SECONDS),
					"the fully consumed selected child enters its real close callback");
			TestReader reader = producer.readers.getLast();
			assertEquals(3, reader.pulled.get());
			assertFalse(owner.isClosed(), "the accepted parent owner stays retained until child close returns");
			assertEquals(1, reader.closeCalls.get());
			releaseClose.countDown();
			assertTrue(pendingHasNext.get(WAIT_SECONDS, TimeUnit.SECONDS),
					"completed full sort publishes its first row");
			assertTrue(result.next() != null, "the probed first ordered row remains available");
			List<BindingSet> remaining = new ArrayList<>();
			while (result.hasNext()) {
				remaining.add(result.next());
			}
			result.close();
			assertEquals(2, remaining.size());
			assertEquals(1, reader.closeCalls.get());
			assertTrue(owner.isClosed(), "draining and closing retires the accepted owner");
			SealedBoundaryTestSupport.orderStage(root, false);
		} finally {
			releaseClose.countDown();
			if (result != null) {
				result.close();
			}
			executor.shutdownNow();
			executor.awaitTermination(WAIT_SECONDS, TimeUnit.SECONDS);
			registrations.close();
		}
	}

	@Test
	void comparisonFailureRemainsPrimaryWhenTheSelectedChildCloseFails() {
		QueryEvaluationException comparisonFailure = new QueryEvaluationException("actual ORDER comparison failure");
		IllegalStateException closeFailure = new IllegalStateException("actual selected child close failure");
		TestTupleFunction producer = rowsFunction();
		KeyFunction key = new KeyFunction(Function.Determinism.VOLATILE);
		RegisteredFunctions registrations = register(producer, key);
		CloseableIteration<BindingSet> result = null;
		try {
			var source = SealedBoundaryTestSupport.source(NativeCompositeOriginFixture.miniData());
			List<BindingSet> ordinary = ordinaryRows(source, producer, key, true);
			assertEquals(2, ordinary.size());
			assertEquals(List.of("A", "B"), representatives(ordinary));
			producer.closeControl = new ReaderCloseControl(null, null, closeFailure);
			QueryRoot root = orderedRoot(producer, key, true);
			Order order = (Order) ((Slice) root.getArg()).getArg();
			assertFalse(QueryEvaluationUtility.isRepeatable(order.getElements().getFirst().getExpr()),
					"the fatal comparison uses an explicitly VOLATILE key, not a pinned stable comparator");
			markOrderSummary(root, true);
			QueryEvaluationStep step = SealedBoundaryTestSupport.nativeStrategy(source, true).precompile(root);
			result = step.evaluate(EmptyBindingSet.getInstance());
			NativeExecutionContext owner = NativeExecutionContextCarrier.contextOf(result);
			assertNotNull(owner);
			TestReader reader = producer.readers.getLast();
			AtomicBoolean callbackWhileReaderLive = new AtomicBoolean();
			key.arm(() -> reader.pulled.get() == 3, () -> {
				callbackWhileReaderLive.set(!reader.eofObserved && !reader.closed.get());
				throw comparisonFailure;
			});
			Throwable actual = assertThrows(RuntimeException.class, result::hasNext);
			SealedBoundaryTestSupport.orderStage(root, true);
			assertTrue(key.invoked.get(), "the selected comparison reached the intentional failure callback");
			assertTrue(callbackWhileReaderLive.get(), "the failing TopK comparison runs before child EOF or close");
			assertSame(comparisonFailure, actual, "actual=" + actual + ", cause=" + actual.getCause()
					+ ", suppressed=" + Arrays.toString(actual.getSuppressed()));
			assertEquals(1, actual.getSuppressed().length);
			assertSame(closeFailure, actual.getSuppressed()[0], "the child close error is suppressed by identity");
			assertEquals(3, reader.pulled.get());
			assertEquals(1, reader.closeCalls.get());
			assertTrue(owner.isClosed(), "the failed owner settles after close failure");
		} finally {
			if (result != null) {
				result.close();
			}
			registrations.close();
		}
	}

